    def attach(self, timeout=30, attach_service_call=None, detach_service_call=None,
               airplane_mode_switcher_text=None, airplane_mode_confirm_button_text=None):
        """
        Do attach: turn on mobile data, turn off airplane mode, check cell id assigned
        :param timeout:
        :param attach_service_call:
        :param detach_service_call:
        :param airplane_mode_switcher_text: Text next to switcher widget that toggles airplane mode
        :param airplane_mode_confirm_button_text: Text on button widget on popup window with confirmation to turn
        airplane mode on or off (if such window does pop up)
        :return:
        """
        self.logger.info('UE attach', extra={'ue_id': self.sn_number})
        is_rooted, su_prefix = self.is_rooted()
        self._turn_on_location_services()
        self.set_airplane_mode(state='0', is_rooted=is_rooted, su_prefix=su_prefix, service_call=attach_service_call,
                               airplane_mode_switcher_text=airplane_mode_switcher_text,
                               airplane_mode_confirm_button_text=airplane_mode_confirm_button_text)
        self.set_mobile_data(state='1', is_rooted=is_rooted, su_prefix=su_prefix)
        if self.ueman.get_mobile_data_settings() != '1':
            self.logger.warning('Mobile data settings not set properly for UE with id:{}'.format(self.sn_number))
        self.wait_for_cell_id_state(timeout, state='1')
        self.assert_ue_attached(timeout, attach_service_call, detach_service_call, is_rooted=is_rooted,
                                su_prefix=su_prefix,
                                airplane_mode_switcher_text=airplane_mode_switcher_text,
                                airplane_mode_confirm_button_text=airplane_mode_confirm_button_text)
        self.logger.debug('Statuses of UE: cell_id:{}, mobile_data_status:{}, airplane_mode_status:{}'.format(
            self.ueman.get_cell_id(), self.ueman.get_mobile_data_settings(), self.ueman.get_airplane_status()),
            extra={'ue_id': self.sn_number})

    def detach(self, timeout=30, detach_service_call=None, attach_service_call=None, airplane_mode_switcher_text=None,
               airplane_mode_confirm_button_text=None):
        """
        Do detach: turn off mobile data, turn on airplane mode, check cell id not assigned
        :param timeout:
        :param detach_service_call:
        :param attach_service_call:
        :param airplane_mode_switcher_text: Text next to switcher widget that toggles airplane mode
        :param airplane_mode_confirm_button_text: Text of the button to confirm airplane mode switch on
        airplane mode on or off (if such window do pops up)
        :return:
        """
        self.logger.info('UE detach', extra={'ue_id': self.sn_number})
        is_rooted, su_prefix = self.is_rooted()
        self.set_mobile_data(state='0', is_rooted=is_rooted, su_prefix=su_prefix)
        if self.ueman.get_mobile_data_settings() != '0':
            self.logger.warning('Mobile data settings not set properly for UE with id:{}'.format(self.sn_number))
        self.set_airplane_mode(state='1', is_rooted=is_rooted, su_prefix=su_prefix, service_call=detach_service_call,
                               airplane_mode_switcher_text=airplane_mode_switcher_text,
                               airplane_mode_confirm_button_text=airplane_mode_confirm_button_text)
        self.wait_for_cell_id_state(timeout, state='0')
        if self.get_cached_ue_model() in self.LTE_CELL_ID_WORKAROUND_MODELS:
            time.sleep(3)
            return
        self.assert_ue_detached(timeout, attach_service_call,
                                detach_service_call, is_rooted=is_rooted, su_prefix=su_prefix,
                                airplane_mode_switcher_text=airplane_mode_switcher_text,
                                airplane_mode_confirm_button_text=airplane_mode_confirm_button_text)
        self.logger.debug("Statuses of UE: cell_id:{}, mobile_data_status:{}, airplane_mode_status:{}".format(
            self.ueman.get_cell_id(), self.ueman.get_mobile_data_settings(), self.ueman.get_airplane_status()),
            extra={'ue_id': self.sn_number})

    def set_mobile_data(self, state, is_rooted=False, su_prefix=None):
        """
        :param state: String - '1' to turn on, '0' - to turn off
        :param is_rooted: Boolean - is device rooted?
        """
        self.set_data_connectivity(state=state, is_rooted=is_rooted, su_prefix=su_prefix)
        # TODO Disabled due to issues with state detection on GSM. This may need to be checked on app side.
        # self.wait_for_mobile_data_state_change(state)
        return True

    def set_data_connectivity(self, state, is_rooted=False, su_prefix=None):
        """
        :param state: String - '1' to turn on, '0' - to turn off
        :param is_rooted: Boolean - is device rooted?
        """
        state_bool = True if state == '1' else False
        self.logger.debug("set mobile data settings")
        ue_model = self.ueman.get_device_model()
        self.logger.debug("get device model = {}".format(ue_model))
        ue_cpu = self.ueman.get_ue_cpu()
        self.logger.debug("get device cpu = {}".format(ue_cpu))
        mobile_data_settings_handler = MobileDataHandler(ue_model=ue_model, ue_cpu=ue_cpu, ue_serial=self.sn_number,
                                                         is_rooted=is_rooted, su_prefix=su_prefix,
                                                         is_qcom_prototype=self.is_qualcomm_prototype,
                                                         ue_manager_protocol_send_function=self.ueman.send_message_set)
        self.logger.debug("calling set_data_connectivity with enable={}".format(state_bool))
        mobile_data_settings_handler.set_data_connectivity(enable=state_bool)

    def keyevent_change_apn(self, apn_name, labels_to_apn_settings, apn_switcher_widget):
        self.logger.info('Trying to change APN to {} with key events.'.format(apn_name),
                         extra={'ue_id': self.sn_number})
        self.logger.debug('Arguments provided to APN change: labels_to_apn_settings: {}, apn_switcher_widget: {}.'
                          .format(labels_to_apn_settings, apn_switcher_widget), extra={'ue_id': self.sn_number})
        labels_path = labels_to_apn_settings.split(',')
        if len(labels_path) < 2:
            raise CannotChangeApnError('Not enough labels to APN settings provided.')
        self._keyevent_go_to_apn_settings_and_click_switcher(apn_name, apn_switcher_widget, labels_path[0],
                                                             labels_path[1:])
        chosen_apn_state = self._keyevent_check_widget_state(widget_class=apn_switcher_widget, widget_text=apn_name)
        if chosen_apn_state != '1':
            self.logger.info(
                'APN change to {} failed. Actual state of APN switch: {}'.format(apn_name, chosen_apn_state),
                extra={'ue_id': self.sn_number})
            self._force_stop_package(package_name='com.android.settings')
            raise CannotChangeApnError('Error when trying to change APN.')
        self._force_stop_package(package_name='com.android.settings')

    def _keyevent_go_to_apn_settings_and_click_switcher(self, apn_name, apn_switcher_widget,
                                                        mobile_network_settings_text, labels_path):
        self._keyevent_go_to_mobile_network_view(mobile_network_settings_text, unlock=True)
        # TODO move swipe_coords param to robot KW
        self._keyevent_enter_through_labels_path(labels_path, swipe_coords=self.KONA_FOR_ARM_64_APN_SWIPE)
        layout = self._keyevent_get_layout_for_trigger_after_widget_text(widget_class=apn_switcher_widget, widget_text=apn_name)
        self._keyevent_enter_element_by_layout(layout)

    def _keyevent_enter_through_labels_path(self, labels, swipe_coords=None):
        for label in labels:
            self._keyevent_enter_element(label, swipe_coords=swipe_coords)

    def _keyevent_check_widget_state(self, widget_class, widget_text):
        layout = self._keyevent_get_layout_for_trigger_after_widget_text(widget_class=widget_class,
                                                                         widget_text=widget_text)
        return self._keyevent_get_widget_state(layout, widget_class=widget_class)

    def set_airplane_mode(self, state, is_rooted=False, su_prefix=None, service_call=None,
                          airplane_mode_switcher_text=None,
                          airplane_mode_confirm_button_text=None):
        """
        :param state: String - '1' to turn on, '0' - to turn off
        :param is_rooted: Boolean - is device rooted?
        :param su_prefix:
        :param service_call:
        :param airplane_mode_switcher_text: Text next to switcher widget that toggles airplane mode
        :param airplane_mode_confirm_button_text: Text on button widget on popup window with confirmation to turn
        airplane mode on or off (if such window do pops up)
        """
        self._synchronize_airplane_mode_settings_with_actual_signal_state(su_prefix=su_prefix)
        if self.ueman.get_airplane_status() == state:
            self.logger.info('UE airplane mode is already in state: {}, no need to send adb commands'.format(state),
                             extra={'ue_id': self.sn_number})
            return
        if state == '1':
            self._choose_method_and_set_airplane_on(is_rooted=is_rooted, su_prefix=su_prefix, service_call=service_call,
                                                    airplane_mode_switcher_text=airplane_mode_switcher_text,
                                                    airplane_mode_confirm_button_text=airplane_mode_confirm_button_text)
            return
        self._choose_method_and_set_airplane_off(is_rooted=is_rooted, su_prefix=su_prefix, service_call=service_call,
                                                 airplane_mode_switcher_text=airplane_mode_switcher_text,
                                                 airplane_mode_confirm_button_text=airplane_mode_confirm_button_text)

    def _choose_method_and_set_airplane_on(self, is_rooted=False, su_prefix=None, service_call=None,
                                           airplane_mode_switcher_text=None, airplane_mode_confirm_button_text=None):
        if airplane_mode_switcher_text:
            self._keyevent_set_airplane_mode_on(airplane_mode_switcher_text=airplane_mode_switcher_text,
                                                airplane_mode_confirm_button_text=airplane_mode_confirm_button_text)
        else:
            self.set_airplane_mode_on(is_rooted=is_rooted, su_prefix=su_prefix, detach_service_call=service_call)

    def _choose_method_and_set_airplane_off(self, is_rooted=False, su_prefix=None, service_call=None,
                                            airplane_mode_switcher_text=None, airplane_mode_confirm_button_text=None):
        if airplane_mode_switcher_text:
            self._keyevent_set_airplane_mode_off(airplane_mode_switcher_text=airplane_mode_switcher_text,
                                                 airplane_mode_confirm_button_text=airplane_mode_confirm_button_text)
        else:
            self.set_airplane_mode_off(is_rooted=is_rooted, su_prefix=su_prefix, attach_service_call=service_call)

    def _keyevent_set_airplane_mode_on(self, airplane_mode_switcher_text=None, airplane_mode_confirm_button_text=None):
        self._keyevent_set_airplane_mode(state='1', airplane_mode_switcher_text=airplane_mode_switcher_text,
                                         airplane_mode_confirm_button_text=airplane_mode_confirm_button_text)

    def _keyevent_set_airplane_mode_off(self, airplane_mode_switcher_text=None, airplane_mode_confirm_button_text=None):
        self._keyevent_set_airplane_mode(state='0', airplane_mode_switcher_text=airplane_mode_switcher_text,
                                         airplane_mode_confirm_button_text=airplane_mode_confirm_button_text)

    def _keyevent_set_airplane_mode(self, state, airplane_mode_switcher_text=None,
                                    airplane_mode_confirm_button_text=None):
        self.logger.info('Trying to {} airplane mode with key events.'.format('enable' if state == '1' else 'disable'),
                         extra={'ue_id': self.sn_number})
        if airplane_mode_confirm_button_text and state == '1':
            self._keyevent_go_to_airplane_mode_view_and_switch_state(widget_text=airplane_mode_switcher_text)
            self._keyevent_enter_element(widget_text=airplane_mode_confirm_button_text)
        else:
            self._keyevent_go_to_airplane_mode_view_and_switch_state(widget_text=airplane_mode_switcher_text)
        self._force_stop_package(package_name='com.android.settings')

    def _force_stop_package(self, package_name='com.android.settings', delay=2):
        time.sleep(delay)
        adb_proxy.adb_force_stop_package(self.sn_number, package_name)

    def _keyevent_check_airplane_mode_switch_state(self, widget_text):
        adb_proxy.adb_start_activity_airplane_mode_settings(self.sn_number, clear_task=True)
        return self._keyevent_check_widget_state(widget_class='android.widget.Switch', widget_text=widget_text)

    @staticmethod
    def _xml_get_coordinates(layout):
        coordinates = str(layout).split("bounds=")[1].replace('"', '').replace('>', '').replace("'", '')
        coordinates = coordinates.replace('][', ',').replace(']', '').replace('[', '')
        coordinates = coordinates.split(',')
        coordinates = [x for x in coordinates if str(x).isdigit()]
        if len(coordinates) >= 2:
            x = int(coordinates[0]) + 10
            y = int(coordinates[1]) + 10
        else:
            x, y = None, None
        return x, y

    @staticmethod
    def _xml_get_state(layout, widget_class='android.widget.Switch'):
        state = str(layout).split(widget_class)[1].split("checked=")[1].replace('"', '').split(' ')[0]
        return "1" if state == "true" else "0" if state == "false" else None

    @staticmethod
    def _xml_get_text(layout):
        try:
            text = str(layout).split("text=")[1].split('"')[1]
            return text if text else None
        except IndexError:
            return None

    @staticmethod
    def _keyevent_raise_attach_detach_exception(state, err_msg):
        if state == '1':
            raise CannotDetachError(err_msg)
        raise CannotAttachError(err_msg)

    def _keyevent_get_layout(self, widget_text, should_raise=False):
        self.logger.info('Trying to get layout for widget_text: {}.'.format(widget_text),
                         extra={'ue_id': self.sn_number})
        full_layout = self._keyevent_get_full_layout()
        layout = self._keyevent_get_widget_text_layout(full_layout, widget_text)
        if not layout and should_raise:
            raise KeyeventsIncorrectLayoutException(
                'Layout {}\ndoes not have expected pattern text: {}.'.format(layout, widget_text))
        return layout

    def _keyevent_get_full_layout(self):
        self.logger.info('Trying to get full layout of current view.', extra={'ue_id': self.sn_number})
        layout, err = adb_proxy.adb_cat_view_layout_xml(self.sn_number)
        for i in range(5):
            if 'null root node returned by UiTestAutomationBridge' in err:
                adb_proxy.adb_wake_up_screen(self.sn_number)
                time.sleep(2)
                layout, err = adb_proxy.adb_cat_view_layout_xml(self.sn_number)
        if not isinstance(layout, six.text_type):
            layout = six.text_type(layout, encoding='utf-8', errors='ignore')
        return layout

    def _keyevent_get_widget_text_layout(self, full_layout, widget_text):
        if widget_text in full_layout:
            layout = full_layout.split('><')
            layout_with_text = [x for x in layout if 'text="{}"'.format(widget_text) in x]
            if not layout_with_text:
                layout_with_text = [x for x in layout if widget_text in x]
            layout = layout_with_text[0]
            self.logger.info('Layout for widget_text {} is {}'.format(widget_text, layout),
                             extra={'ue_id': self.sn_number})
            return layout

    def _keyevent_get_layout_for_element_by_resource_id(self, resource_id='android:id/summary', widget_text=None,
                                                        should_raise=True):
        return self._keyevent_get_layout_for_trigger_after_widget_text(widget_class=resource_id,
                                                                       widget_text=widget_text,
                                                                       should_raise=should_raise)

    def _keyevent_get_layout_for_element_spinner(self, widget_class='android.widget.Spinner', widget_text=None,
                                                 should_raise=True):
        return self._keyevent_get_layout_for_trigger_after_widget_text(widget_class=widget_class,
                                                                       widget_text=widget_text,
                                                                       should_raise=should_raise)

    def _keyevent_get_layout_for_trigger_after_widget_text(self, widget_class='android.widget.Switch', widget_text=None,
                                                           should_raise=True):
        self._keyevent_find_element(widget_text)
        full_layout = self._keyevent_get_full_layout().split('><')
        for element in full_layout:
            if widget_text in element:
                full_layout = full_layout[full_layout.index(element):]
        for element in full_layout:
            if widget_class in element:
                return element.encode('ascii', 'ignore')
        if should_raise:
            raise KeyeventsIncorrectLayoutException(
                'Cannot find the switch {} element for {}.'.format(widget_class, widget_text))

    def _keyevent_find_element(self, widget_text, should_raise=True, swipe_coords=None):
        if swipe_coords is not None:
            adb_proxy.adb_swipe(self.sn_number, *swipe_coords)
        adb_proxy.adb_roll_max_up(self.sn_number)
        for i in range(15):
            layout = self._keyevent_get_layout(widget_text=widget_text, should_raise=False)
            if widget_text not in str(layout):
                adb_proxy.adb_roll_step_down(self.sn_number)
            else:
                return layout
        if should_raise:
            raise KeyeventsIncorrectLayoutException(
                'Cannot find the widget text {} in current gui site.'.format(widget_text))

    def _keyevent_get_widget_coordinates(self, layout):
        self.logger.info('Trying to get coordinates of layout element {}.'.format(layout),
                         extra={'ue_id': self.sn_number})
        x, y = self._xml_get_coordinates(layout)
        self.logger.info('Coordinates for layout element: x = {}, y = {}.'.format(x, y),
                         extra={'ue_id': self.sn_number})
        return x, y

    def _keyevent_get_widget_state(self, layout, widget_class='android.widget.Switch'):
        self.logger.info('Trying to get state of layout element {}.'.format(layout), extra={'ue_id': self.sn_number})
        state = self._xml_get_state(layout, widget_class)
        self.logger.info('State for layout element: {}'.format(state), extra={'ue_id': self.sn_number})
        return state

    def _keyevent_get_widget_text(self, layout):
        self.logger.info('Trying to get text from layout element {}.'.format(layout), extra={'ue_id': self.sn_number})
        text = self._xml_get_text(layout)
        self.logger.info('Text for layout element: {}'.format(text), extra={'ue_id': self.sn_number})
        return text

    def _keyevent_get_widget_coordinates_and_state(self, layout):
        self.logger.info('Trying to get coordinates and state of layout element {}..'.format(layout),
                         extra={'ue_id': self.sn_number})
        x, y = self._keyevent_get_widget_coordinates(layout)
        state = self._keyevent_get_widget_state(layout)
        self.logger.info('Coords and state of layout element {}.: x = {}, y = {}, state = {}.'.format(
            layout, x, y, state), extra={'ue_id': self.sn_number})
        return x, y, state

    def _keyevent_enter_element(self, widget_text, should_raise=True, swipe_coords=None):
        layout = self._keyevent_find_element(widget_text, should_raise=should_raise, swipe_coords=swipe_coords)
        if layout:
            x, y = self._keyevent_get_widget_coordinates(layout)
            adb_proxy.adb_wake_up_screen(self.sn_number)
            time.sleep(2)
            adb_proxy.adb_tap_coordinates(self.sn_number, x, y)
            time.sleep(2)
        else:
            if should_raise:
                raise KeyeventsIncorrectLayoutException(
                    'Cannot find the widget text {} in current gui site.'.format(widget_text))

    def _keyevent_enter_element_by_layout(self, layout):
        x, y = self._keyevent_get_widget_coordinates(layout)
        time.sleep(2)
        adb_proxy.adb_tap_coordinates(self.sn_number, x, y)
        time.sleep(2)

    def _unlock_screen(self):
        self.logger.debug('Unlocking UE screen.')
        time.sleep(0.8)
        adb_proxy.adb_run_cmd(self.sn_number, 'shell', ['input', 'keyevent', adb_proxy.AdbShellCommands.KEYCODE_MENU])

    def _keyevent_go_to_airplane_mode_view_and_switch_state(self, widget_text, unlock=True):
        self.logger.info('Entering Airplane Mode view on ue.', extra={'ue_id': self.sn_number})
        adb_proxy.adb_start_activity_airplane_mode_settings(self.sn_number, clear_task=True)
        if unlock:  # additional screen unlock currently is not generating any errors even if not needed
            # in case of errors, unlock param should be moved to UE config
            self._unlock_screen()
        self._keyevent_enter_element(widget_text)

    def _keyevent_go_to_mobile_network_view(self, widget_text, unlock=False):
        self.logger.info('Entering Mobile Network view on ue.', extra={'ue_id': self.sn_number})
        adb_proxy.adb_start_activity_mobile_networks_settings(self.sn_number, clear_task=True)
        if unlock:
            self._unlock_screen()
        self._keyevent_enter_element(widget_text)

    def _keyevent_go_to_phone_call_view(self):
        self.logger.info('Entering Phone Call view on ue.', extra={'ue_id': self.sn_number})
        adb_proxy.adb_start_activity_phone_call_view(self.sn_number, clear_task=True)

    def _keyevent_go_to_preferred_network_type_menu(self, mobile_network_widget, setting_network_mode_widget):
        self.logger.info('Entering Preferred network type view on ue.', extra={'ue_id': self.sn_number})
        self._keyevent_go_to_mobile_network_view(mobile_network_widget)
        self._keyevent_enter_element(setting_network_mode_widget)

    def _keyevent_set_preferred_network_mode(self, preferred_network_mode='NR only',
                                             mobile_network_widget='Mobile network',
                                             setting_network_mode_widget='Preferred network type'):
        self.logger.info('Setting preferred network mode {} on ue.'.format(preferred_network_mode),
                         extra={'ue_id': self.sn_number})
        python_ver = OsCommands().get_python_version()
        if python_ver.major == 2 or (python_ver.major == 3 and python_ver.minor < 7):
            self.logger.warning("Suggested python to use keyevent methods is at least 3.7")
        self._keyevent_go_to_preferred_network_type_menu(mobile_network_widget=mobile_network_widget,
                                                         setting_network_mode_widget=setting_network_mode_widget)
        self._keyevent_enter_element(widget_text=preferred_network_mode)
        self._force_stop_package(package_name='com.android.settings')

    def _secretcode_set_preferred_network_mode(self, preferred_network_mode='NR only', secret_code='*#*#4636#*#*',
                                               path_to_set_net_mode=None):
        self.logger.info('Setting preferred network mode {} on ue.'.format(preferred_network_mode),
                         extra={'ue_id': self.sn_number})
        self._keyevent_close_all_aps()
        self._keyevent_go_to_phone_call_view()
        self._enter_secret_code(secret_code=secret_code)
        if not path_to_set_net_mode:
            path_to_set_net_mode = self.SECRET_CODE_MENU_PATH_SAMSUNG
        self._keyevent_enter_through_labels_path(labels=path_to_set_net_mode[:-1])
        layout = self._keyevent_get_layout_for_element_spinner(widget_text=path_to_set_net_mode[-1], should_raise=False)
        self._keyevent_enter_element_by_layout(layout)
        self._keyevent_enter_element(widget_text=preferred_network_mode)

    def _enter_secret_code(self, secret_code):
        adb_proxy.adb_input_text(ue_sn=self.sn_number, text=secret_code)

    def _keyevent_get_layout_for_current_network_mode(self, setting_network_mode_widget):
        self._keyevent_find_element(setting_network_mode_widget)
        adb_proxy.adb_roll(self.sn_number, 1, 1)
        full_layout = self._keyevent_get_full_layout().split('><')
        for element in full_layout:
            if setting_network_mode_widget in element:
                full_layout = full_layout[full_layout.index(element):]
        for element in full_layout:
            for entry in self.NETWORK_MODE_ENTRIES:
                if entry in element:
                    element = element.encode('ascii', 'ignore')
                    return element.decode('utf-8', 'ignore')
        raise KeyeventsIncorrectLayoutException(
            'Cannot find current network mode under {}.'.format(setting_network_mode_widget))

    def _keyevent_read_preferred_network_mode(self, mobile_network_widget='Mobile network',
                                              setting_network_mode_widget='Preferred network type'):
        self._keyevent_go_to_mobile_network_view(mobile_network_widget)
        self.logger.info('Reading actual preferred network mode from ue.', extra={'ue_id': self.sn_number})
        layout = self._keyevent_get_layout_for_current_network_mode(setting_network_mode_widget)
        preferred_network_mode = layout.split('text=')[1].split('"')[1]
        self.logger.info('Preferred network mode read from ue: {}.'.format(preferred_network_mode),
                         extra={'ue_id': self.sn_number})
        self._force_stop_package(package_name='com.android.settings')
        return preferred_network_mode

    def _keyevent_close_all_aps(self, widget_text='Close all'):
        self.logger.info('Closing all open apps in app switcher on ue.', extra={'ue_id': self.sn_number})
        adb_proxy.adb_open_app_switcher(self.sn_number)
        self._keyevent_enter_element(widget_text=widget_text)
        self.logger.info('All apps should be closed now on ue. Awaiting 60s for NAA app restart.',
                         extra={'ue_id': self.sn_number})
        adb_proxy.adb_await_activity_service(ue_sn=self.sn_number, package_name=adb_proxy.NAA_PACKAGE_NAME,
                                             activity_service_name=adb_proxy.NAA_ACTIVITY_NAME,
                                             wait_time=60, should_raise=True)

    def _synchronize_airplane_mode_settings_with_actual_signal_state(self, su_prefix=None):
        signal_strength = int(self.get_ue_info("SIGNAL_STRENGTH", 10))
        signal_detected = signal_strength != -1
        if signal_detected:
            self.logger.debug(
                "Signal detected ({}) but airplane_mode_on - correcting settings".format(signal_strength))
            adb_proxy.adb_run_cmd(self.sn_number, "shell", [adb_proxy.AdbShellCommands.AIRPLANE_MODE_SETTINGS_OFF])
            if self.is_qualcomm_prototype:
                adb_proxy.adb_run_cmd(self.sn_number, "shell",
                                      [su_prefix, adb_proxy.AdbShellCommands.AIRPLANE_MODE_BROADCAST_OFF])
            return
        if not signal_detected:
            self.logger.debug(
                "Signal not detected ({}) but not airplane_mode_on - correcting settings".format(signal_strength))
            adb_proxy.adb_run_cmd(self.sn_number, "shell", [adb_proxy.AdbShellCommands.AIRPLANE_MODE_SETTINGS_ON])
            if self.is_qualcomm_prototype:
                adb_proxy.adb_run_cmd(self.sn_number, "shell",
                                      [su_prefix, adb_proxy.AdbShellCommands.AIRPLANE_MODE_BROADCAST_ON])

    def assert_ue_attached(self, timeout, attach_service_call, detach_service_call, is_rooted=False, su_prefix=None,
                           airplane_mode_switcher_text=None, airplane_mode_confirm_button_text=None):
        """
        Assert that Ue is attached, if not execute additional actions and check again
        :param timeout:
        :param attach_service_call:
        :param detach_service_call:
        :param is_rooted:
        :param su_prefix:
        :param airplane_mode_switcher_text:
        :param airplane_mode_confirm_button_text:
        :return:
        """
        if self.cell_id_empty(self.ueman.get_cell_id()):
            if airplane_mode_switcher_text:
                self._keyevent_set_airplane_mode_on(airplane_mode_switcher_text=airplane_mode_switcher_text,
                                                    airplane_mode_confirm_button_text=airplane_mode_confirm_button_text)
                self._keyevent_set_airplane_mode_off(airplane_mode_switcher_text=airplane_mode_switcher_text,
                                                     airplane_mode_confirm_button_text=airplane_mode_confirm_button_text)
            else:
                self.set_airplane_mode_on(is_rooted, su_prefix, detach_service_call)
                self.set_airplane_mode_off(is_rooted, su_prefix, attach_service_call)
            self.wait_until_cell_id_state(timeout, state='1')
        else:
            self.logger.info('UE cell id in expected state, cell id: {}.'.format(self.ueman.get_cell_id()),
                             extra={'ue_id': self.sn_number})

    def assert_ue_detached(self, timeout, attach_service_call, detach_service_call, is_rooted=False, su_prefix=None,
                           airplane_mode_switcher_text=None, airplane_mode_confirm_button_text=None):
        """
        Assert that Ue is detached, if not execute additional actions and check again
        :param timeout:
        :param attach_service_call:
        :param detach_service_call:
        :param is_rooted:
        :param su_prefix:
        :param airplane_mode_switcher_text:
        :param airplane_mode_confirm_button_text:
        :return:
        """
        if not self.cell_id_empty(self.ueman.get_cell_id()):
            if airplane_mode_switcher_text:
                self._keyevent_set_airplane_mode_off(airplane_mode_switcher_text=airplane_mode_switcher_text,
                                                     airplane_mode_confirm_button_text=airplane_mode_confirm_button_text)
                self._keyevent_set_airplane_mode_on(airplane_mode_switcher_text=airplane_mode_switcher_text,
                                                    airplane_mode_confirm_button_text=airplane_mode_confirm_button_text)
            else:
                self.set_airplane_mode_off(is_rooted, su_prefix, attach_service_call)
                self.set_airplane_mode_on(is_rooted, su_prefix, detach_service_call)
            self.wait_until_cell_id_state(timeout, state='0')
        else:
            self.logger.info('UE cell id in expected state, cell id: {}.'.format(self.ueman.get_cell_id()),
                             extra={'ue_id': self.sn_number})

    def _create_attach_detach_handler(self, is_rooted, su_prefix=None, attach_service_call=None,
                                      detach_service_call=None):
        ue_model = self.ueman.get_device_model()
        try:
            android_version = self.ueman.get_android_sdk()
        except AppMobileVersionIncorrect as e:
            self.logger.warning(e)
            android_version = self.ueman.get_android_version()
        return AttachDetachHandler(self.ueman, serial_number=self.sn_number, ue_model=ue_model,
                                   android_version=android_version,
                                   is_rooted=is_rooted, su_prefix=su_prefix,
                                   is_qualcomm=self.is_qualcomm_prototype,
                                   attach_service_call_number=attach_service_call,
                                   detach_service_call_number=detach_service_call)

    def set_airplane_mode_off(self, is_rooted, su_prefix=None, attach_service_call=None):
        """
        :param is_rooted:
        :return:
        """
        attach_detach_handler = self._create_attach_detach_handler(is_rooted=is_rooted, su_prefix=su_prefix,
                                                                   attach_service_call=attach_service_call)
        attach_detach_handler.attach()
        if attach_service_call is None:
            self.wait_for_airplane_mode_state(timeout=20, state='0')
        else:
            self.logger.debug("attach via service call")

    def set_airplane_mode_on(self, is_rooted, su_prefix=None, detach_service_call=None):
        """
        :param is_rooted:
        :return:
        """
        attach_detach_handler = self._create_attach_detach_handler(is_rooted=is_rooted, su_prefix=su_prefix,
                                                                   detach_service_call=detach_service_call)
        attach_detach_handler.detach()
        if detach_service_call is None:
            self.wait_for_airplane_mode_state(timeout=20, state='1')
        else:
            self.logger.debug("detach via service call")

    def wait_for_airplane_mode_state(self, timeout=10, state='0'):
        """
        Wait for attach/detach completion, airplane mode switch off(attach)/on(detach)
        :param timeout: time allowed to complete airplane mode change
        :param state: '0' for airplane mode off and '1' for airplane mode on
        :return:
        """
        self.logger.info('wait for UE airplane mode state: {}'.format(state), extra={'ue_id': self.sn_number})
        worker = SleepyLoopWorker(timeout=timeout)
        worker.set_get_value_callback(self.ueman.get_airplane_status)
        worker.set_value_validator(lambda airplane_mode_state: airplane_mode_state == state)
        worker.set_log_value_callback(
            lambda airplane_mode_state: self.logger.info('Airplane Mode Status = {}'.format(airplane_mode_state)))
        _, success = worker.execute_work()
        self.logger.info('wait for attach, success = {}'.format(success), extra={'ue_id': self.sn_number})
        if not success:
            self.logger.error("Airplane mode not changed", extra={'ue_id': self.sn_number})
            if state == '0':
                raise CannotAttachError("Airplane mode is not changed in attach on: {}".format(self.sn_number))
            else:
                raise CannotDetachError("Airplane mode is not changed in detach on: {}".format(self.sn_number))
        return success

    def add_new_apn_entry(self, json_string):
        """
        Tries to insert new APN entry into NAA
        :param json_string: JSON string containing APN configuration
        :return: Message from UE indicating whether operation succeed
        """
        return self.ueman.add_new_apn_entry(json_string)

    def remove_apn_entry(self, entry_name):
        """
        Tries to remove APN entry with given name from UE
        :param entry_name: name of APN to remove
        :return: Message from UE indicating whether operation succeed
        """
        return self.ueman.remove_apn_entry(entry_name)

    def set_device_owner(self):
        """Tries to set NAA as an active admin and device owner of the UE, enabling adding and removing APNs"""
        result, err = adb_proxy.adb_run_cmd(self.sn_number, 'shell',
                                            ['dpm set-active-admin --user current com.nokia.android.application/.device_admin.DeviceAdminReceiver'])
        if 'Not allowed to set the device owner because there are already some accounts on the device' in err:
            return 'ERROR: Failed to set NAA as active admin. Have You removed all accounts from target device?'
        result, err = adb_proxy.adb_run_cmd(self.sn_number, 'shell',
                                            ['dpm set-device-owner --user current com.nokia.android.application/.device_admin.DeviceAdminReceiver'])
        if 'Not allowed to set the device owner because there are already some accounts on the device' in err:
            return 'ERROR: Failed to set NAA as device owner. Have You removed all accounts from target device?'
        return 'OK: NAA is now device owner.'

    def is_naa_device_owner(self):
        """
        Checks whether NAA is set as a device owner
        :return: Message from UE indicating whether operation succeed
        """
        return self.ueman.is_naa_device_owner()

    def wait_until_cell_id_state(self, timeout=20, state='1'):
        """
        Wait for cell_id appearing/disappearing
        :param timeout: time allowed to complete cell id check
        :param state: '0' for disappearing and '1' for appearing
        :return:
        """
        success = self.wait_for_cell_id_state(timeout, state)
        if not success:
            self.logger.error("Cell id did not change", extra={'ue_id': self.sn_number})
            if state == '1':
                raise CannotAttachError("Cell id is not changed for UE: {}\n"
                                        "Check UE logs if proper serving cell is being heard.".format(self.sn_number))
            else:
                raise CannotDetachError("Cell id is not changed for UE: {}".format(self.sn_number))
        return success

    def cell_id_empty(self, cell_id):
        """
        Check if cell id has got value treated as empty
        :param cell_id:
        :return:
        """
        if not cell_id:
            return True
        is_cell_id_empty = cell_id == "Airplane mode is on" or int(cell_id) in [0, -1, 2147483647]
        self.logger.debug("Is cell id empty?: {}".format(cell_id))
        return is_cell_id_empty

    def wait_for_cell_id_state(self, timeout=30, state='1'):
        """
        Wait for cell_id appearing/disappearing
        :param timeout: time allowed to complete cell id check
        :param state: '0' for disappearing and '1' for appearing
        :return:
        """
        self.logger.info('wait for cell id change', extra={'ue_id': self.sn_number})
        worker = SleepyLoopWorker(timeout=timeout)
        worker.set_get_value_callback(self.ueman.get_cell_id)
        if state == '1':
            worker.set_value_validator(lambda ci: not self.cell_id_empty(ci))
            worker.set_log_value_callback(
                lambda ci: self.logger.debug('Wait for cell id after attach, now cell id = {}'.format(ci),
                                             extra={'ue_id': self.sn_number}))
        else:
            worker.set_value_validator(lambda ci: self.cell_id_empty(ci))
            worker.set_log_value_callback(
                lambda ci: self.logger.debug('Wait for cell id after detach, now cell id = {}'.format(ci),
                                             extra={'ue_id': self.sn_number}))
        _, success = worker.execute_work()
        return success

    def _enb_id_empty(self, enb_id):
        is_enb_empty = enb_id == "Airplane mode is on" or int(enb_id) == -1
        self.logger.debug("Is enb_id empty?: {}".format(is_enb_empty))
        return is_enb_empty

    def _has_signal(self, signal_strength):
        # TODO UeManager supported only. Need to commonize with NAA.
        return 'Airplane mode is on' not in str.lower(str(signal_strength))

    def wait_for_call_finish(self, call_time):
        """
        :param func:
        :return:
        """
        self.logger.info("wait for finish call", extra={'ue_id': self.sn_number})
        end_time = time.time() + call_time
        while time.time() <= end_time:
            next_sleep = time.time() + 1
            calling_state = self.get_calling_state()
            self.logger.info("call step with step %d", call_time)
            if 'OUT' in calling_state or 'INC' in calling_state:
                to_sleep = next_sleep - time.time()
                if to_sleep > 0:
                    time.sleep(to_sleep)
                self.logger.info(calling_state)
                call_time -= 1
                continue
            elif 'IDL' in calling_state:
                self.logger.info("got IDL, break while")
                return 0
        self.logger.debug("call end_call", extra={'ue_id': self.sn_number})
        self.end_call()
        return 1

    def end_call(self):
        """End voice call"""
        self.ueman.end_call()

    def get_calling_state(self):
        """
        Gets calling state
        :return: IDL, OUT1235456, IN123456
        """
        return self.ueman.get_calling_state()

    def call(self, number, call_time):
        """
        :param func:
        :return:
        """
        self.make_call(number)
        if call_time is None:
            return
        time.sleep(2)
        self.wait_for_call_finish(int(call_time))

    def make_call(self, number, with_video=False):
        """
        Makes voice/video call to given number.
        :param number:
        :param with_video:
        """
        self.ueman.make_call(number, with_video)

    def _verify_exceptional_ue_for_emergency(self):
        actual_ue = {"model": "", "sdk": 0, "os": 0}
        try:
            actual_ue = {
                "model": self.ueman.get_device_model(),
                "sdk": int(self.ueman.get_android_sdk()),
                "os": int(self.ueman.get_android_version())
            }
        except UeManagerException as exc:
            self.logger.debug(
                "UE identification property not accomplished. Used default value.\n{}".format(exc))
        for except_ue in UES_EXCCEPTIONAL_DATA:
            if except_ue.MODEL in actual_ue['model'] and except_ue.SDK <= actual_ue['sdk'] and except_ue.OS <= actual_ue['os']:
                self.logger.debug("Actual UE matches exceptional implementation. (model={}, sdk={}, os={})".format(actual_ue['model'],
                                                                                                                   actual_ue['sdk'],
                                                                                                                   actual_ue['os']))
                return True, except_ue
        return False, None

    def make_emergency_call(self, number):
        """
        Make emergency call
        For Oppo Find 5X Pro there is an exception which is handled
        :return: None
        """
        adb_proxy.adb_start_activity(self.sn_number, self._package_name, adb_proxy.NAA_ACTIVITY_NAME)
        is_exceptional, exc_ue_data = self._verify_exceptional_ue_for_emergency()

        if is_exceptional:
            # Exceptional UE way only!
            MSG_INFO = "This is 'make_emergency_call' with handled variant for model" + \
                       " {}, sdk={}, os={}.\n".format(exc_ue_data.MODEL, exc_ue_data.SDK, exc_ue_data.OS)
            self.logger.info(MSG_INFO)
            time.sleep(1)
            adb_proxy.adb_run_cmd(self.sn_number, "shell", ["am", "start", "-W", "-n", "com.android.phone/com.android.phone.EmergencyDialer"])
            time.sleep(1)
            for digit in number:
                if digit.isdigit():
                    # tap digit
                    adb_proxy.adb_send_tap(self.sn_number, exc_ue_data.TAPS[digit]['x'], exc_ue_data.TAPS[digit]['y'])
                    time.sleep(0.5)
            # tap CALL
            adb_proxy.adb_send_tap(self.sn_number, exc_ue_data.TAPS['CALL']['x'], exc_ue_data.TAPS['CALL']['y'])
            time.sleep(0.5)
        else:
            self.ueman.make_emergency_call(number)
            adb_proxy.adb_send_key_code(self.sn_number, adb_proxy.AdbShellCommands.KEYCODE_CALL)
        return

    def end_emergency_call(self):
        TIMEOUT = 10.0
        is_exceptional, exc_ue_data = self._verify_exceptional_ue_for_emergency()

        if is_exceptional:
            # Exceptional UE way only!
            MSG_INFO = "Emergency call ended by exceptional way specified for UE model" + \
                       " {}, sdk={}, os={}.\n".format(exc_ue_data.MODEL, exc_ue_data.SDK, exc_ue_data.OS)
            self.logger.debug(MSG_INFO)

            end_time_start, end_time_end = time.time(), time.time()
            while True:
                if end_time_end - end_time_start > TIMEOUT:
                    raise Exception("Timeout for End Emergency Call")
                self.send_key_code(adb_proxy.AdbShellCommands.KEYCODE_WAKEUP)
                time.sleep(0.5)
                adb_proxy.adb_send_tap(self.sn_number, exc_ue_data.TAPS['ENDCALL']['x'], exc_ue_data.TAPS['ENDCALL']['y'])
                end_time_end = time.time()
                if not self.ueman.is_in_call():
                    break
        else:
            for _ in range(5):
                # Send multiple KEYCODE_DPAD_DOWN just in case to select end call button (differs on UEs)
                # KEYCODE_ENDCALL would be simpler but on some Qualcomm prototypes triggers different action
                self.send_key_code(adb_proxy.AdbShellCommands.KEYCODE_DPAD_DOWN)
                time.sleep(0.1)
            self.send_key_code(adb_proxy.AdbShellCommands.KEYCODE_ENTER)
        return

    def is_emergency_phone_number(self, number):
        """Checks if a number is an emergency one"""
        return self.ueman.is_emergency_phone_number(number)

    def is_in_call(self):
        """Returns whether there is an ongoing phone call (can be in dialing, ringing, active or holding states)"""
        return self.ueman.is_in_call()

    def wait_for_new_network_mode(self, new_mode, timeout=60):
        """
        Waits until appear given network mode.
        :param new_mode:
        :param timeout: maybe be float
        :return:
        """
        worker = SleepyLoopWorker(timeout=timeout)
        worker.set_get_value_callback(self.ueman.get_current_preferred_net)
        worker.set_value_validator(lambda mode: mode == new_mode)
        worker.set_log_value_callback(lambda mode: self.logger.info('Current network mode = {}'.format(mode)))
        if worker.is_already_achieved():
            self.logger.info('Current network mode = {}. No need to change.'.format(new_mode))
            return new_mode

        self.ueman.set_network(new_mode)
        result_mode, succeed = worker.execute_work()
        if not succeed:
            raise CanNotChangeNetworkModeError
        return result_mode

    def get_mobile_app_package_name(self):
        """
        Gets package name of mobile application.
        :return:
        """
        return self._package_name

    def _change_network_mode_shell_based(self, network_mode, attach_service_call=None, detach_service_call=None,
                                         airplane_mode_switcher_text=None, airplane_mode_confirm_button_text=None):
        entries = self._get_global_settings_entries("preferred_network_mode")
        network_mode_id = self.ueman.network_mode_names2nums[network_mode]
        for entry in entries:
            cmd = "settings put global {} {}".format(entry[0], network_mode_id)
            result, err = adb_proxy.adb_run_cmd(self.sn_number, "shell", [cmd])
            self.logger.debug("Change network mode result: {}, and error: {}".format(result, err))
        self.detach(detach_service_call=detach_service_call, airplane_mode_switcher_text=airplane_mode_switcher_text,
                    airplane_mode_confirm_button_text=airplane_mode_confirm_button_text)
        self.attach(attach_service_call=attach_service_call, airplane_mode_switcher_text=airplane_mode_switcher_text,
                    airplane_mode_confirm_button_text=airplane_mode_confirm_button_text)

    def get_preferred_network_mode(self, network_mode_switch_method=None, mobile_network_text=None,
                                   setting_network_mode_text=None):
        """Return current preferred network mode"""
        if str(network_mode_switch_method).lower() == 'keyevents' or str(
                network_mode_switch_method).lower() == 'secretcode':
            pref_net_mode = self._keyevent_read_preferred_network_mode(mobile_network_text, setting_network_mode_text)
        else:
            pref_net_mode_num = self._get_global_settings_entries("preferred_network_mode")[0][1]
            pref_net_mode = [self.ueman.network_mode_nums2names[int(net_mode)] for net_mode in pref_net_mode_num.split(",")]
        return pref_net_mode

    def _get_global_settings_entries(self, entry_substring):
        self.logger.debug("Getting global settings")
        rawoutput = self.run_cmd_via_adb_shell(["settings", "list", "global"])[0]
        self.logger.debug("Global settings: {}".format(rawoutput))
        entries = []
        for line in rawoutput.split('\n'):
            if entry_substring in line:
                line_parsed = line.split("=")
                if line_parsed:
                    entries.append(line_parsed)
        if not entries:
            raise CanNotReadNetworkModeError(
                "Can't read network mode settings on UE: {}, adb output: {}".format(self.sn_number, rawoutput))
        self.logger.debug("Parsed settings list based on '{}' substring: {}".format(entry_substring, entries))
        return entries

    def change_network_mode(self, network_mode, attach_service_call=None, detach_service_call=None,
                            airplane_mode_switcher_text=None, airplane_mode_confirm_button_text=None,
                            network_mode_switch_method=None, mobile_network_widget=None,
                            setting_network_mode_widget=None, secret_code=None):
        """
        Change network mode with adb
        :param network_mode:
        :param attach_service_call:
        :param detach_service_call:
        :param network_mode_switch_method:
        :param mobile_network_widget:
        :param setting_network_mode_widget:
        :param secret code:
        :return:
        """
        if str(network_mode_switch_method).lower() == 'keyevents':
            self._keyevent_set_preferred_network_mode(network_mode, mobile_network_widget, setting_network_mode_widget)
        elif str(network_mode_switch_method).lower() == 'secretcode':
            self._secretcode_set_preferred_network_mode(network_mode, secret_code)
        else:
            self._change_network_mode_shell_based(network_mode, attach_service_call, detach_service_call,
                                                  airplane_mode_switcher_text, airplane_mode_confirm_button_text)

    def _keyevents_change_and_validate_nr_mode(self, nr_mode, nr_card_name, settings_text):
        """
        Change preferred 5G NR mode with adb keyevents.
        """
        self.logger.info('Trying to change preferred 5G NR mode to {} with keyevents'.format(nr_mode),
                         extra={'ue_id': self.sn_number})
        self._keyevent_open_preferred_nr_mode_settings(settings_text)

        current_nr_mode = self._keyevent_get_current_nr_mode(nr_card_name)
        if current_nr_mode != nr_mode:
            self._keyevent_set_nr_mode(nr_card_name, nr_mode)
            current_nr_mode = self._keyevent_get_current_nr_mode(nr_card_name)

        adb_proxy.adb_force_stop_package(self.sn_number, 'com.android.settings')
        if current_nr_mode == nr_mode:
            self.logger.info('Successfully set \"Preferred 5G NR Mode\" to {}'.format(nr_mode),
                             extra={'ue_id': self.sn_number})
        else:
            self.logger.info('Failed to set \"Preferred 5G NR Mode\" to \"{}\". Please check if given parameters are '
                             'correct'.format(nr_mode), extra={'ue_id': self.sn_number})
            raise KeyeventsPreferredNrModeException(
                "Failed to set preferred 5G mode on {} to {}".format(nr_card_name, nr_mode))

    def _keyevent_open_preferred_nr_mode_settings(self, settings_text):
        self.logger.info('Entering Development Settings view on ue.', extra={'ue_id': self.sn_number})
        adb_proxy.adb_start_activity_development_settings(self.sn_number, clear_task=True)

        self.logger.info('Searching for \"Prefer 5G NR Mode\"', extra={'ue_id': self.sn_number})
        try:
            self._keyevent_enter_element(settings_text)
        except KeyeventsIncorrectLayoutException:
            raise KeyeventsPreferredNrModeException("Failed to enter preferred 5G mode settings")
        return True

    def _keyevent_get_current_nr_mode(self, nr_card_name):
        layout = self._keyevent_get_layout_for_element_by_resource_id(resource_id='android:id/summary',
                                                                      widget_text=nr_card_name)
        current_nr_mode = self._keyevent_get_widget_text(layout)
        if current_nr_mode:
            try:
                return self.supported_nr_state_to_nr_mode_dict[current_nr_mode]
            except KeyError:
                raise Exception(
                    "Cannot validate changing Preferred 5G Nr Mode. There is no support for mode '{}' extracted from development "
                    "settings. Currently supported are: {}".format(current_nr_mode, list(
                        self.supported_nr_state_to_nr_mode_dict.keys())))
        else:
            self.logger.info(
                'Failed to read current \"Preferred 5G NR Mode\" state on {}. Please check if given parameters are '
                'correct and if it is possible to manually change \"Preferred 5G NR Mode\"'.format(nr_card_name),
                extra={'ue_id': self.sn_number})
            adb_proxy.adb_force_stop_package(self.sn_number, 'com.android.settings')
            raise KeyeventsPreferredNrModeException("Failed to read current preferred 5G mode")

    def _keyevent_set_nr_mode(self, nr_card_name, nr_mode):
        self.logger.info('Trying to set \"Preferred 5G NR Mode\" to {}'.format(nr_mode),
                         extra={'ue_id': self.sn_number})
        self._keyevent_enter_element(nr_card_name)
        self._keyevent_enter_element(nr_mode)

    def get_signal_strength(self, timeout=10):
        """
        :param timeout: time limit the get signal strength
        :return:
        """
        given_signal_strength, succeed = self._loop_until_get_valid_value(
            timeout=timeout,
            lambda_get_value=lambda: self.ueman.get_signal(),
            lambda_is_value_ok=lambda ss: self._has_signal(ss),
            msg_tmp='Signal strength = {}',
            refresh_time=1)
        if not succeed:
            return '-1'
        return given_signal_strength

    def get_enb_id(self, timeout=10):
        """

        :param timeout: int in seconds
        :return:
        """
        # TODO: maybe enable user to set refresh_time ? now refresh_time = 1 second
        given_enb_id, succeed = self._loop_until_get_valid_value(timeout=timeout,
                                                                 lambda_get_value=lambda: self.ueman.get_enb_id(),
                                                                 lambda_is_value_ok=lambda enb: not self._enb_id_empty(
                                                                     enb), msg_tmp='eNB ID = {}',
                                                                 refresh_time=1)
        if not succeed:
            self.logger.debug("get_enb_id not succeed")
            if self.is_airplane_mode():
                raise NoCellIdUeIsDetachedError('Can not get enb ID, because UE is detached')
            else:
                self.logger.debug('Can not get enb ID')
                return given_enb_id
        return given_enb_id

    def _get_ip_by_apn(self, apn_name):
        apn_connection_data = self._get_interface_name_and_ip_for_apn(apn_name)
        ip = apn_connection_data[apn_name]["ip_address"]
        if not ip:
            raise NoIpError('Can not find any assigned IP for apn {} on {} UE'.format(apn_name, self.sn_number))
        return ip

    def _get_interface_name_and_ip_for_apn(self, apn_name=None):
        apn_connection_data = self._get_apn_connection_data(apn_name)
        try:
            interface = apn_connection_data.split("InterfaceName: ")[1].split(" ")[0]
            ip = apn_connection_data.split("LinkAddresses: [")[1].split("]")[0].split("/")[0].strip(" ")
        except IndexError:
            raise NoIpError('Can not find any assigned IP for apn {} on {} UE'.format(apn_name, self.sn_number))
        return {apn_name: {"interface_name": interface, "ip_address": ip}}

    def _get_apn_connection_data(self, apn_name=None):
        self.logger.debug("Getting dumpsys connectivity data for apn: {}".format(apn_name))
        apn_connection_data = ''.join(
            self.run_cmd_via_adb_shell(["dumpsys", "connectivity", "|", "grep", "{}".format(apn_name)]))
        if not apn_connection_data:
            apn_mapping = self._get_apns_interfaces_mapping()
            apns = [apn for apn in apn_mapping.keys()]
            raise NoApnConnectivityDataError(
                'Can not find any connectivity data for apn {} on {} UE. Found: {}'.format(apn_name, self.sn_number, apns))
        self.logger.debug("Got connectivity data for apn {}: {}".format(apn_name, apn_connection_data))
        return str(apn_connection_data)

    def get_ip(self, timeout=10, ip_version=4, interface_name_pattern=None, apn_name=None):
        """
        Gets the UE IP
        :param timeout: time allowed to get the IP
        :param ip_version: version of ip: 4 or 6
        :param interface_name_pattern: e.g.: rmnet_data0
        :param apn_name: return ip for specific apn
        :return: UE IP string
        """
        if apn_name:
            return self._get_ip_by_apn(apn_name)
        ip, succeed = self._loop_until_get_valid_value(
            timeout=timeout,
            lambda_get_value=lambda: self.ueman.get_ip(ip_version=int(ip_version),
                                                       interface_name_pattern=interface_name_pattern),
            lambda_is_value_ok=lambda ip: ip is not None and ip != "",
            msg_tmp='IP = {}',
            refresh_time=1)
        if not succeed:
            raise NoIpError('Can not find any assigned IPv{} on {} UE'.format(ip_version, self.sn_number))
        return ip

    def _get_apns_interfaces_mapping(self):
        connectivity_data = self._get_network_agent_info_data()
        apn_mapping = {}
        for connection_info in connectivity_data:
            if "extra" in connection_info:
                try:
                    apn_name = connection_info.split("extra: ")[1].split(" ")[0].strip(",,{,},[,], ,")
                    interface_name = connection_info.split("InterfaceName: ")[1].split(" ")[0].strip(",,{,},[,], ,")
                    ip_address = connection_info.split("LinkAddresses: ")[1].split("/")[0].strip(",,{,},[,], ,")
                    self.logger.debug(
                        "Apn interface data. APN: {}, interface: {}, ip: {}".format(apn_name, interface_name,
                                                                                    ip_address))
                except IndexError:
                    raise NoIpError(
                        'Problem with parsing connection info: {} on {} UE'.format(connection_info, self.sn_number))
                apn_mapping[apn_name] = {"interface_name": interface_name, "ip_address": ip_address}
        return apn_mapping

    def _get_network_agent_info_data(self):
        self.logger.debug("Getting dumpsys connectivity data")
        connectivity_data = list(
            str(self.run_cmd_via_adb_shell(["dumpsys", "connectivity", "|", "grep", "NetworkAgentInfo{ "])).split(
                "\\n"))
        connectivity_data_android13 = list(
            str(self.run_cmd_via_adb_shell(["dumpsys", "connectivity", "|", "grep", "NetworkAgentInfo{ "])))
        if not connectivity_data or not connectivity_data_android13 or connectivity_data == ["('', '')"]:
            raise NoApnConnectivityDataError('Can not find any connectivity data on {} UE'.format(self.sn_number))
        return connectivity_data

