    def get_ue_info(self, info, timeout=None, network_mode_switch_method=None, mobile_network_text=None,
                    setting_network_mode_text=None):
        """
        :param info:
        :param timeout: string/int/float in seconds
        :param network_mode_switch_method:
        :param mobile_network_text:
        :param setting_network_mode_text:
        :return:
        """
        methods_dict = self._get_ue_info_methods_dict()
        sub_info = None
        split_info = info.split(':')
        info = split_info[0]
        if len(split_info) > 1:
            sub_info = split_info[1]
        if info not in methods_dict:
            raise ValueError(
                "unsupported info type %s, supported are: %s" % (info, ", ".join(list(methods_dict.keys()))))
        info_output = self._invoke_with_timeout_if_need(info, methods_dict, timeout=timeout,
                                                        network_mode_switch_method=network_mode_switch_method,
                                                        mobile_network_text=mobile_network_text,
                                                        setting_network_mode_text=setting_network_mode_text)
        self.logger.info(info_output, extra={'ue_id': self.sn_number})
        if sub_info and sub_info in info_output:
            try:
                return info_output[sub_info]
            except KeyError:
                self.logger.error("Unsupported sub info for info type {}. Info from ue={}. ".format(info, info_output))
        return info_output

    @staticmethod
    def _invoke_with_timeout_if_need(info, methods_dict, timeout, network_mode_switch_method=None,
                                     mobile_network_text=None, setting_network_mode_text=None):
        """
        :param info:
        :param methods_dict:
        :param timeout: string/int/float in seconds
        :param network_mode_switch_method:
        :return:
        """
        if timeout is not None and info in ['CELL_ID', 'IP', 'SIGNAL_STRENGTH']:
            return methods_dict[info](timeout=timeout)
        if (str(network_mode_switch_method).lower() == 'keyevents' or str(
                network_mode_switch_method).lower() == 'secretcode') \
                and info in ['PREFERRED_NET_MODE']:
            return methods_dict[info](network_mode_switch_method=network_mode_switch_method,
                                      mobile_network_text=mobile_network_text,
                                      setting_network_mode_text=setting_network_mode_text)
        return methods_dict[info]()

