    def set_wifi_state(self, state):
        """
        Sets desired state of wifi on UE
        :param state: String - '1' to turn on, '0' - to turn off
        :return: True, if wifi state changed to desired or already been
        :raises FailToTurnOnWiFi: If failed to turn wifi on
        :raises FailToTurnOffWiFi: If failed to tur wifi off
        :raises UnexpectedCmdResultException: If unsuspected output occurred
        :raises Exception:
        """
        is_rooted, su_prefix = self.is_rooted()

        self._adb_set_wifi_state(state, is_rooted, su_prefix)

        if not self._adb_verify_wifi_state(state, is_rooted, su_prefix):
            result = self._ueman_set_wifi_state(state)
            if result != 'success':
                if result != 'fail':
                    raise UnexpectedCmdResultException(result)
                self._raise_wifi_failures(state)
        return True

    def _adb_check_wifi_state(self, is_rooted, su_prefix):
        cmd = 'settings get global wifi_on'
        if is_rooted and su_prefix:
            cmd = "{} {}".format(su_prefix, cmd)
        stdout_wifi_state, stderr_wifi_state = self.run_cmd_via_adb('shell', [cmd])
        return stdout_wifi_state

    def _adb_verify_wifi_state(self, state, is_rooted, su_prefix):
        stdout_wifi_state = str(self._adb_check_wifi_state(is_rooted, su_prefix))
        self.logger.info('UE wifi state: {}'.format(stdout_wifi_state), extra={'ue_id': self.sn_number})

        if state == "1" and "0" not in stdout_wifi_state:  # confirmed turn on
            return True
        elif state == "0" and "0" in stdout_wifi_state:  # confirmed turn off
            return True
        return False

    def _adb_set_wifi_state(self, state, is_rooted, su_prefix):
        adb_shell_cmd = 'svc wifi enable' if state == "1" else 'svc wifi disable' if state == "0" else None
        if not adb_shell_cmd:
            raise Exception("Unrecognised argument: {}. State should be in ['0', '1']".format(state))

        if is_rooted and su_prefix:
            adb_shell_cmd = '{} {}'.format(su_prefix, adb_shell_cmd)
        adb_proxy.adb_run_cmd(self.sn_number, "shell", [adb_shell_cmd])

    def _ueman_set_wifi_state(self, state):
        return self.ueman.turn_wifi_on() if state == "1" else self.ueman.turn_wifi_off()

    def _raise_wifi_failures(self, state):
        if state == "1":
            raise FailToTurnOnWiFi
        else:
            raise FailToTurnOffWiFi

