    def ftp_start_ul(self, host_ip, username, password, remote_path, direction, file_size, test_index):
        """
        Start FTP transfer with given hostname with given direction etc.
        :param hostname: FTP host hostname
        :param port: FTP connection port
        :param username: FTP host username
        :param password: FTP host password
        :param remote_path: FTP file path
        :param file_size: FTP data file size for upload
        :param test_index: FTP data test_index for upload file reference
        :param direction: Direction of FTP connection Uplink or Downlink
        """
        self.logger.debug(
            'Starting FTP Data Transfer Upload of file size {} to {} and path {}.'.format(file_size, host_ip,
                                                                                          remote_path))
        self.ueman.ftp_start_ul(host_ip, username, password, remote_path, direction, file_size, test_index)

    def ftp_start_dl(self, host_ip, username, password, remote_path, direction):
        """
        Start FTP transfer with given hostname with given direction etc.
        :param hostname: FTP host hostname
        :param port: FTP connection port
        :param username: FTP host username
        :param password: FTP host password
        :param remote_path: FTP file path
        :param direction: Direction of FTP connection Uplink or Downlink
        """
        self.logger.debug('Starting FTP Data Transfer Download from {} and path {}.'.format(host_ip, remote_path))
        self.ueman.ftp_start_dl(host_ip, username, password, remote_path, direction)

